# Headless run of the two analysis classes on the sample data and on edge cases. Run from the module root, best in jamovi's own R:  Rscript tests/smoke.R
suppressMessages({library(jmvcore); library(R6); library(ggplot2)})
for (f in c("R/00jmv.R", "R/common.R", list.files("R", "^engine_.*[.]R$", full.names = TRUE), "R/guide.R", list.files("R", "[.]h[.]R$", full.names = TRUE), list.files("R", "[.]b[.]R$", full.names = TRUE))) source(f)
het <- read.csv("data/sim_het_trial.csv", stringsAsFactors = TRUE); hom <- read.csv("data/sim_homogeneous_trial.csv", stringsAsFactors = TRUE)
CV <- c("age", "female", "income", "baseline", "edu", "urban", "hhsize", "health", "noise1", "noise2")
bad <- 0
run <- function(label, fn, data, expect_error = FALSE, ...) {
    a <- list(...)
    fm <- formals(fn)
    for (n in setdiff(names(fm)[vapply(fm, function(z) identical(z, quote(expr = )), logical(1))], c("data", names(a)))) a[n] <- list(NULL)
    t0 <- Sys.time()
    r <- tryCatch({ res <- do.call(fn, c(list(data = data), a)); invisible(capture.output(print(res))); "ok" }, error = function(e) paste("ERROR:", conditionMessage(e)))
    good <- if (expect_error) grepl("^ERROR", r) else r == "ok"
    cat(sprintf("%-52s %5.1fs  %s\n", label, as.numeric(difftime(Sys.time(), t0, units = "secs")), if (good) substr(r, 1, 80) else paste("UNEXPECTED:", r))); if (!good) bad <<- bad + 1
    invisible(NULL)
}
q <- function(...) list(...)
run("hetgeneric lasso default", hetgeneric, het, outcome = "y", treat = "arm", covs = CV, nsplit = 10)
run("hetgeneric all learners", hetgeneric, het, outcome = "y", treat = "arm", covs = CV, lrnLasso = TRUE, lrnRidge = TRUE, lrnEnet = TRUE, lrnRf = TRUE, lrnOls = TRUE, nsplit = 6)
run("hetgeneric nominal covariate, 3 groups", hetgeneric, transform(het, edu = factor(edu)), outcome = "y", treat = "arm", covs = c("edu", "female", "baseline"), groups = 3, nsplit = 8)
run("hetgeneric HC1, no sorting, no CLAN, no plot", hetgeneric, het, outcome = "y", treat = "arm", covs = CV, vcov = "hc1", monotonize = FALSE, clan = FALSE, plot = FALSE, nsplit = 8)
run("hetgeneric classical, 1se, level 90", hetgeneric, het, outcome = "y", treat = "arm", covs = CV, vcov = "const", lambdaRule = "1se", level = 90, nsplit = 8)
run("hetgeneric control and treatment values", hetgeneric, het, outcome = "y", treat = "arm", control = "control", armTreat = "treated", covs = CV, nsplit = 6)
run("hetgeneric known propensity score", hetgeneric, transform(het, ps = 0.5), outcome = "y", treat = "arm", covs = CV, prop = "ps", nsplit = 6)
run("hetgeneric notes and guide", hetgeneric, het, outcome = "y", treat = "arm", covs = CV, showHelp = TRUE, showGuide = TRUE, nsplit = 6)
run("hetgeneric missing values", hetgeneric, within(het, { y[1:50] <- NA; age[60:80] <- NA }), outcome = "y", treat = "arm", covs = CV, nsplit = 6)
run("hetgeneric homogeneous data", hetgeneric, hom, outcome = "y", treat = "arm", covs = c("x1", "x2", "x3"), groups = 3, nsplit = 8)
run("hetgeneric no covariates (hint)", hetgeneric, het, outcome = "y", treat = "arm", covs = NULL)
run("hetgeneric no learner (error)", hetgeneric, het, TRUE, outcome = "y", treat = "arm", covs = CV, lrnLasso = FALSE)
run("hetgeneric outcome as covariate (error)", hetgeneric, het, TRUE, outcome = "y", treat = "arm", covs = c("y", "age"))
run("hetgeneric bad treatment value (error)", hetgeneric, het, TRUE, outcome = "y", treat = "arm", armTreat = "zzz", covs = CV)
run("hetgeneric tiny sample (error)", hetgeneric, het[1:30, ], TRUE, outcome = "y", treat = "arm", covs = CV)
run("hetgeneric propensity score of 1 (error)", hetgeneric, transform(het, ps = 1), TRUE, outcome = "y", treat = "arm", covs = CV, prop = "ps", nsplit = 6)
run("hetprofile default (all covariates)", hetprofile, het, outcome = "y", treat = "arm", covs = CV, nsplit = 8)
run("hetprofile chosen moderators, two learners", hetprofile, het, outcome = "y", treat = "arm", covs = c("age", "female", "baseline", "noise1"), moderators = c("female", "baseline"), lrnRf = TRUE, nsplit = 5)
run("hetprofile nominal moderator, HC1, no plot, notes and guide", hetprofile, transform(het, edu = factor(edu)), outcome = "y", treat = "arm", covs = c("edu", "baseline"), moderators = "edu", vcov = "hc1", plot = FALSE, showHelp = TRUE, showGuide = TRUE, nsplit = 5)
run("hetprofile homogeneous data", hetprofile, hom, outcome = "y", treat = "arm", covs = c("x1", "x2", "x3"), nsplit = 8)
run("hetprofile moderator not among the covariates (error)", hetprofile, het, TRUE, outcome = "y", treat = "arm", covs = c("age", "female"), moderators = "baseline", nsplit = 5)
run("hetprofile no covariates (hint)", hetprofile, het, outcome = "y", treat = "arm", covs = NULL)
run("hetrate default", hetrate, het, outcome = "y", treat = "arm", covs = CV, nsplit = 8, nboot = 30)
run("hetrate two learners, no plot", hetrate, het, outcome = "y", treat = "arm", covs = CV, lrnRf = TRUE, plot = FALSE, nsplit = 5, nboot = 30)
run("hetrate notes and guide, level 90, 1se", hetrate, het, outcome = "y", treat = "arm", covs = CV, showHelp = TRUE, showGuide = TRUE, level = 90, lambdaRule = "1se", nsplit = 5, nboot = 30)
run("hetrate homogeneous data", hetrate, hom, outcome = "y", treat = "arm", covs = c("x1", "x2", "x3"), nsplit = 8, nboot = 30)
run("hetrate known propensity score", hetrate, transform(het, ps = 0.5), outcome = "y", treat = "arm", covs = CV, prop = "ps", nsplit = 5, nboot = 30)
run("hetrate no covariates (hint)", hetrate, het, outcome = "y", treat = "arm", covs = NULL)
run("hetrate no learner (error)", hetrate, het, TRUE, outcome = "y", treat = "arm", covs = CV, lrnLasso = FALSE)
run("hetpolicy default", hetpolicy, het, outcome = "y", treat = "arm", covs = CV, nsplit = 10)
run("hetpolicy cost 0.5, two learners", hetpolicy, het, outcome = "y", treat = "arm", covs = CV, cost = 0.5, lrnRf = TRUE, nsplit = 6)
run("hetpolicy cost so high that nobody is treated", hetpolicy, het, outcome = "y", treat = "arm", covs = CV, cost = 100, nsplit = 6)
run("hetpolicy notes and guide", hetpolicy, het, outcome = "y", treat = "arm", covs = CV, showHelp = TRUE, showGuide = TRUE, nsplit = 6)
run("hetpolicy no covariates (hint)", hetpolicy, het, outcome = "y", treat = "arm", covs = NULL)
run("hetpolicy no learner (error)", hetpolicy, het, TRUE, outcome = "y", treat = "arm", covs = CV, lrnLasso = FALSE)
cat(if (bad == 0) "\nAll checks passed.\n" else sprintf("\n%d check(s) failed.\n", bad))
if (bad > 0) quit(status = 1)
